const labels6=['혼자 떠올렸어요','아는 식으로 찾았어요','그림을 보고 찾았어요'];
let s6={bank:[],rounds:0,done:false,pending:[]};
const key6=(n,g)=>`${n} × ${g}`;
function import6(){for(const c of s5.cards){const [n,g]=c.key.split(' × ').map(Number);if(!s6.bank.some(b=>b.key===c.key))s6.bank.push({key:c.key,n,g,answer:n*g,source:'5단계에서 찾은 식',level:['바로 떠올림','아는 식으로 해결','그림을 보고 해결'].indexOf(c.route),stars:0,history:[],imported:true})}for(const [n,g] of [[2,4],[5,3],[2,6],[5,4],[2,5]])if(!s6.bank.some(c=>c.key===key6(n,g)))s6.bank.push({key:key6(n,g),n,g,answer:n*g,source:'앞 단계에서 만난 식',level:null,stars:0,history:[]})}
function start6(){import6();view='stage6';app.innerHTML=`<section class="activity"><span class="pill">6단계 · 내 구구단 카드함</span><h1>가리고, 떠올리고, 확인해요</h1><p>답이 바로 생각나지 않으면 아는 식이나 그림을 열어도 좋아요. 시간제한은 없어요.</p><div class="actions"><button class="primary" onclick="begin6(false)">4~5장 짧게 연습하기</button><button onclick="begin6(true)">서로 다른 5장으로 확인하기</button></div>${s6.done?'<p class="feedback good">6단계 확인을 마쳤어요! 카드함은 언제든 다시 열어 연습할 수 있어요.</p>':''}<h2>내 카드 ${s6.bank.length}장</h2><p class="small">${s5.cards.length?'5단계에서 해결한 식을 가져왔어요.':'이번 페이지에 5단계 기록이 없어, 앞 단계에서 만난 2단·5단 카드로 시작해요.'} 기록과 별은 이 브라우저에 저장되어 다음에도 이어 볼 수 있어요.</p><div class="saved-cards">${s6.bank.map(c=>`<article><strong>${c.key}</strong><p>${c.level===null?'먼저 떠올려 볼 카드':labels6[c.level]}</p><small>${c.source}</small><p aria-label="별 ${c.stars}개">${c.stars?'★'.repeat(c.stars):'아직 별이 없어요'}</p></article>`).join('')}</div><details><summary>함께하는 어른에게</summary><p>별은 이전 풀이보다 적은 도움으로 해결했을 때만 더해집니다. 틀리거나 단서를 써도 별은 줄지 않습니다. 이 기록은 다음 문제를 고르는 데 사용합니다.</p><p>5장 확인은 서로 다른 식을 끝까지 해결하고, 단서를 쓴 경우 다시 가린 식에도 답하면 마칩니다. 단서를 쓴 카드는 다음 짧은 활동에서도 다시 만납니다.</p></details></section>`}
function rotateOrder6(items){if(items.length<2)return items;const offset=s6.rounds%items.length;return items.slice(offset).concat(items.slice(0,offset))}
function begin6(check){import6();const recent=s6.bank.filter(c=>c.imported).slice(-2);const familiar=s6.bank.filter(c=>!c.imported).slice(0,2);const need=s6.bank.filter(c=>s6.pending.includes(c.key)||c.level>0).sort((a,b)=>Number(s6.pending.includes(b.key))-Number(s6.pending.includes(a.key)));let selected=[];function add(c){if(c&&!selected.some(x=>x.key===c.key))selected.push(c)}if(check){[...recent,...familiar,...need,...s6.bank].forEach(add);selected=selected.slice(0,5)}else{if(s6.rounds>0)need.slice(0,2).forEach(add);[...recent,...familiar,...s6.bank].forEach(add);selected=selected.slice(0,4)}// Interleave learned and familiar cards without unit-order dependence.
selected=rotateOrder6(selected);if(selected.length>=4)selected=[selected[0],selected[2],selected[1],...selected.slice(3)];s6.check=check;s6.queue=selected.map(c=>c.key);s6.pos=0;s6.results=[];s6.rounds++;s6.repeated=false;initCard6()}
const card6=()=>s6.bank.find(c=>c.key===s6.queue[s6.pos]);
function initCard6(){Object.assign(s6,{phase:'front',level:0,hint:'',fill:0,wrong:false,msg:'잠깐 생각해 보고 답을 써 보세요. 서두르지 않아도 괜찮아요.',committed:false});render6()}
function hint6(type){s6.level=Math.max(s6.level,type==='picture'?2:1);s6.hint=type;s6.phase='front';s6.msg=type==='picture'?'마지막 빈 묶음에 같은 개수만큼 채워 보세요.':'아는 식에서 한 묶음의 개수만큼 더해 보세요.';render6()}
function fill6(delta){s6.fill=Math.max(0,Math.min(card6().n+1,s6.fill+delta));s6.msg=s6.fill===card6().n?'새 묶음을 채웠어요. 앞의 답에 이 묶음의 개수를 더해요.':'한 묶음에 몇 개씩 들어 있는지 보고 채워요.';render6()}
function picture6(full=false){const c=card6();return `<div class="group-grid">${Array.from({length:c.g-1},(_,i)=>`<div class="group-box"><small>${i+1}묶음</small>${Array(c.n).fill('●').join(' ')}</div>`).join('')}<div class="group-box new"><small>마지막 묶음</small>${Array(full?c.n:s6.fill).fill('●').join(' ')||'비어 있어요'}${full?'':`<div class="controls"><button onclick="fill6(-1)" aria-label="하나 꺼내기">−</button><button onclick="fill6(1)" aria-label="하나 담기">+</button></div>`}</div></div>`}
function answer6(value){const c=card6();if(!Number.isInteger(value)||value<0){s6.msg='숫자로 답을 써 주세요.';render6();return}if(value!==c.answer){s6.wrong=true;s6.msg=s6.hint?`${c.n*(c.g-1)}에서 한 묶음만큼 늘어요. 한 묶음에는 몇 개씩 있나요?`:'다시 생각해 봐요. 막히면 아는 식이나 묶음 그림을 열어도 좋아요.';render6();return}if(s6.phase==='recall'){commit6();s6.phase='solved';s6.msg='그림을 가리고도 다시 떠올렸어요!';render6();return}s6.phase='back';s6.msg='내가 쓴 답과 그림을 함께 확인해요.';render6()}
function hide6(){if(s6.phase!=='back')return;if(s6.level>0){s6.phase='recall';s6.hint='';s6.fill=0;s6.msg='이제 그림과 단서를 가렸어요. 같은 식의 답을 다시 떠올려요.';render6()}else{commit6();nextCard6()}}
function commit6(){if(s6.committed)return;const c=card6(),old=c.level;const improved=old!==null&&s6.level<old;if(improved)c.stars++;c.level=s6.level;c.history.push({level:s6.level,corrected:s6.wrong,round:s6.rounds});s6.results.push({key:c.key,level:s6.level,improved});s6.pending=s6.pending.filter(k=>k!==c.key);if(s6.level>0||s6.wrong)s6.pending.push(c.key);s6.committed=true;if(!s6.check&&!s6.repeated&&s6.queue.length<5&&s6.pos<s6.queue.length-1&&(s6.level>0||s6.wrong)){s6.queue.push(c.key);s6.repeated=true}}
function nextCard6(){s6.pos++;if(s6.pos>=s6.queue.length){end6();return}initCard6()}
function render6(){view='stage6';const c=card6(),back=s6.phase==='back',solved=s6.phase==='solved';let content='';if(back){content=`<div class="equation">${c.key} = ${c.answer}</div>${picture6(true)}<button class="primary" onclick="hide6()">${s6.level?'다시 가리고 답하기':'확인했어요 · 다음 카드'}</button>`}else if(solved){content=`<p class="feedback good">${labels6[s6.level]}</p>${s6.results.at(-1)?.improved?'<p>★ 지난번보다 적은 도움으로 찾았어요. 별이 하나 늘었어요!</p>':''}<button class="primary" onclick="nextCard6()">다음 카드 →</button>`}else{if(s6.hint)content+=`<div class="clue-strip">아는 식 <b>${c.n} × ${c.g-1} = ${c.n*(c.g-1)}</b></div>`;if(s6.hint==='picture')content+=picture6();if(s6.hint)content+=`<div class="equation">${c.n*(c.g-1)} + ${c.n} = □</div>`;content+=`<form id="answerForm6"><label for="answerInput6">${c.key}의 답</label><div class="answer-entry"><input id="answerInput6" type="number" inputmode="numeric" min="0" max="99" required autocomplete="off"><button type="submit" class="primary">답 확인</button></div></form><div class="actions"><button onclick="hint6('equation')">아는 식 보기</button><button onclick="hint6('picture')">묶음 그림 보기</button></div>`}app.innerHTML=`<div class="topline"><span class="pill">6단계 · ${s6.check?'서로 다른 5장 확인':'짧게 떠올리기'}</span><span class="small">${s6.pos+1} / ${s6.queue.length}장</span></div><section class="activity"><h1 class="recall-face">${c.key}${back?'':' = ?'}</h1>${s6.queue.indexOf(c.key)<s6.pos?'<p class="small">다른 카드 뒤에서 다시 만났어요.</p>':''}<div class="workspace">${content}</div><p class="feedback" role="status">${s6.msg}</p><button onclick="start6()">카드함으로</button></section>`;const form=document.querySelector('#answerForm6');if(form)form.onsubmit=e=>{e.preventDefault();const raw=document.querySelector('#answerInput6').value;answer6(raw.trim()===''?NaN:Number(raw))}}
function end6(){if(s6.check&&new Set(s6.results.map(r=>r.key)).size===5)s6.done=true;app.innerHTML=`<section class="activity"><span class="pill">${s6.check?'5장 확인 완료':'짧은 연습 완료'}</span><h1>${s6.check?'막혀도 스스로 끝까지 찾았어요!':'오늘의 카드 연습을 마쳤어요!'}</h1><p>${s6.results.length}장의 카드를 해결했어요. 단서를 사용한 것도 성공이에요.</p><div class="saved-cards">${s6.results.map(r=>`<article><strong>${r.key}</strong><p>${labels6[r.level]}</p>${r.improved?'<p>★ 별 하나 추가</p>':''}</article>`).join('')}</div><p>도움이 필요했던 식은 다음 활동에서 먼저 다시 떠올려 볼 수 있어요.</p>${s6.done?'<p class="feedback good">6단계 완료! 7단계에서는 생활 속에 구구단을 써 봐요.</p><p class="small">7단계에서 직접 생활 문제를 만들어 보세요.</p>':''}<div class="actions"><button class="primary" onclick="start7()">7단계 문제 만들기</button><button onclick="start6()">내 카드함 보기</button><button class="primary" onclick="begin6(${s6.check?'false':'true'})">${s6.check?'다음에 볼 카드로 짧게 연습':'서로 다른 5장으로 확인'}</button><button onclick="home()">전체 단계</button></div></section>`}
